import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useLocation, useNavigate } from 'react-router-dom';

// --- NAVBAR (Zdt ghir l-logic dyal smiya) ---
const Navbar = ({ cartCount }) => {
  const location = useLocation();
  const isActive = (path) => location.pathname === path;
  const userName = localStorage.getItem('userName');

  const handleLogout = () => {
    localStorage.clear();
    window.location.href = "/";
  };

  return (
    <nav className="bg-white/95 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">
        <Link to="/" className="flex items-center space-x-3">
          <div className="bg-orange-600 p-2 rounded-full shadow-md flex items-center justify-center">
            <svg width="24" height="24" viewBox="0 0 512 512" fill="white" xmlns="http://www.w3.org/2000/svg">
              <path d="M416 0c-35.3 0-64 28.7-64 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416z" />
            </svg>
          </div>
          <span className="font-black text-xl tracking-tighter text-gray-900 uppercase italic">Fast<span className="text-orange-600">Délice</span></span>
        </Link>

        <div className="hidden md:flex space-x-8 text-[12px] font-black uppercase text-gray-800">
          {[{ name: 'Accueil', path: '/' }, { name: 'Menu', path: '/menu' }, { name: 'À Propos', path: '/about' }, { name: 'Contact', path: '/contact' }].map((link) => (
            <Link key={link.path} to={link.path} className={`relative pb-1 transition-all duration-300 hover:text-orange-600 ${isActive(link.path) ? 'text-orange-600' : ''}`}>
              {link.name}
              {isActive(link.path) && <span className="absolute bottom-0 left-0 w-full h-0.5 bg-orange-600 rounded-full"></span>}
            </Link>
          ))}
        </div>

        <div className="flex items-center space-x-4">
          <Link to="/panier" className="relative flex items-center space-x-2 text-gray-800 hover:text-orange-600 transition">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17" />
            </svg>
            <span className="bg-orange-600 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center">{cartCount}</span>
          </Link>

          {userName ? (
            <div className="flex items-center space-x-4">
              <span className="text-gray-900 font-black uppercase text-[11px] tracking-widest border-b-2 border-orange-600 pb-1">Salut, {userName}</span>
              <button onClick={handleLogout} className="text-red-600 font-black uppercase text-[10px] hover:underline">Quitter</button>
            </div>
          ) : (
            <>
              <Link to="/register" className="text-gray-900 hover:text-orange-600 text-[11px] font-black uppercase tracking-widest transition">S'inscrire</Link>
              <Link to="/login" className="bg-orange-600 text-white px-5 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest hover:bg-gray-900 transition shadow-lg">Connexion</Link>
            </>
          )}
        </div>
      </div>
    </nav>
  );
};

// --- LAYOUT (DYALK) ---
const PageLayout = ({ children, title }) => (
  <div className="relative min-h-screen">
    <div className="fixed inset-0 z-0">
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="bg" />
      <div className="absolute inset-0 bg-black/50 backdrop-blur-[4px]"></div>
    </div>
    <div className="relative z-10 max-w-7xl mx-auto px-6 py-16">
      {title && (
        <div className="text-center mb-16">
          <h2 className="text-5xl md:text-7xl font-black text-white italic tracking-tighter uppercase drop-shadow-2xl">{title}</h2>
          <div className="h-1.5 w-20 bg-orange-600 mx-auto mt-4 rounded-full"></div>
        </div>
      )}
      {children}
    </div>
  </div>
);

// --- REGISTER (M-RIGEL) ---
const Register = () => {
  const [formData, setFormData] = useState({ name: '', email: '', password: '' });
  const navigate = useNavigate();
  const handleRegister = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://127.0.0.1:8000/api/register/', formData);
      alert("Account created! Now you can login.");
      navigate('/login');
    } catch (err) { alert("Error: Email already exists."); }
  };
  return (
    <PageLayout title="Créer un Compte">
      <div className="max-w-md mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
        <form className="space-y-6" onSubmit={handleRegister}>
          <input type="text" placeholder="NOM COMPLET" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold uppercase" onChange={(e) => setFormData({...formData, name: e.target.value})} required />
          <input type="email" placeholder="EMAIL" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setFormData({...formData, email: e.target.value})} required />
          <input type="password" placeholder="MOT DE PASSE" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setFormData({...formData, password: e.target.value})} required />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">S'inscrire</button>
        </form>
      </div>
    </PageLayout>
  );
};

// --- LOGIN (M-RIGEL) ---
const Login = () => {
  const [credentials, setCredentials] = useState({ email: '', password: '' });
  const navigate = useNavigate();
  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/login/', credentials);
      localStorage.setItem('token', res.data.token);
      localStorage.setItem('userName', res.data.user || "Kawthar");
      alert("Bienvenue!");
      window.location.href = "/";
    } catch (err) { alert("Email or Password incorrect."); }
  };
  return (
    <PageLayout title="Connexion">
      <div className="max-w-md mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
        <form className="space-y-6" onSubmit={handleLogin}>
          <input type="email" placeholder="EMAIL" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setCredentials({...credentials, email: e.target.value})} required />
          <input type="password" placeholder="MOT DE PASSE" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setCredentials({...credentials, password: e.target.value})} required />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">Se Connecter</button>
        </form>
      </div>
    </PageLayout>
  );
};

// --- ABOUT (RJ3T L-KTIBA DYALK) ---
const About = () => (
  <PageLayout title="Notre Passion">
    <div className="max-w-5xl mx-auto bg-white/10 backdrop-blur-xl p-12 rounded-[3.5rem] border border-white/20 text-white italic text-center">
      Depuis 2026, FastDélice redéfinit la gastronomie rapide au Maroc. Excellence et rapidité.
    </div>
  </PageLayout>
);

// --- CONTACT (RJ3T L-KTIBA DYALK) ---
const Contact = () => (
  <PageLayout title="Contactez-Nous">
    <div className="max-w-4xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-10">
      <div className="bg-white/10 p-10 rounded-[3rem] text-white italic">
        <h3 className="text-orange-600 font-black mb-4">COORDONNÉES</h3>
        <p>123 Boulevard Gourmand, Casablanca</p>
      </div>
      <form className="bg-black/40 p-10 rounded-[3rem] space-y-4 shadow-2xl">
        <input placeholder="NOM" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white font-bold" />
        <button className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest">Envoyer</button>
      </form>
    </div>
  </PageLayout>
);

// --- HOME (DYALK) ---
const Home = () => (
  <PageLayout>
    <div className="text-center py-16">
      <h1 className="text-7xl md:text-9xl font-black text-white mb-6 italic drop-shadow-2xl">Fast<span className="text-orange-600">Délice</span></h1>
      <Link to="/menu" className="bg-orange-600 text-white px-14 py-5 rounded-full font-black uppercase tracking-widest hover:bg-white hover:text-orange-600 transition shadow-2xl inline-block">Commander Maintenant</Link>
    </div>
  </PageLayout>
);

// --- MENU (DYALK) ---
const Menu = ({ categories, addToCart }) => {
  const [selectedItem, setSelectedItem] = useState(null);
  return (
    <PageLayout title="Menu">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {categories.flatMap(c => c.dishes).map(item => (
          <div key={item.id} className="bg-black/40 border border-white/10 rounded-[3rem] overflow-hidden text-center p-8 group">
             <div className="h-64 overflow-hidden mb-4"><img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition duration-500" /></div>
             <h3 className="text-2xl font-black text-white uppercase italic">{item.name}</h3>
             <p className="text-orange-500 font-black text-2xl mb-4">{item.price} DH</p>
             <button onClick={() => setSelectedItem(item)} className="w-full py-4 bg-white text-black rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-orange-600 hover:text-white transition">Commander</button>
          </div>
        ))}
      </div>
      {selectedItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-md p-4">
           <div className="bg-white rounded-[3rem] p-10 max-w-sm w-full text-center">
             <h3 className="text-2xl font-black italic uppercase mb-8">Mode de Service</h3>
             <button onClick={() => { addToCart({...selectedItem, type: 'Sur Place'}); setSelectedItem(null); }} className="w-full py-4 bg-gray-100 mb-4 rounded-2xl font-black uppercase">🍽️ Sur Place</button>
             <button onClick={() => { addToCart({...selectedItem, type: 'À Emporter'}); setSelectedItem(null); }} className="w-full py-4 bg-gray-900 text-white rounded-2xl font-black uppercase">🛍️ À Emporter</button>
           </div>
        </div>
      )}
    </PageLayout>
  );
};

// --- PANIER (RJ3T L-KTIBA DYALK) ---
const Panier = ({ cart }) => (
  <PageLayout title="Panier">
    <div className="max-w-2xl mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] text-white">
      {cart.length === 0 ? <p className="text-center opacity-60">Panier vide.</p> : (
        <div className="space-y-6 font-bold">
          {cart.map((item, i) => <div key={i} className="flex justify-between border-b border-white/10 pb-4"><span>{item.name} ({item.type})</span><span>{item.price} DH</span></div>)}
          <div className="text-2xl font-black pt-6 flex justify-between"><span>Total:</span><span className="text-orange-600">{cart.reduce((a, b) => a + parseFloat(b.price), 0)} DH</span></div>
        </div>
      )}
    </div>
  </PageLayout>
);

export default function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);
  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/').then(res => setCategories(res.data)).catch(e => console.log(e));
  }, []);

  return (
    <Router>
      <div className="min-h-screen bg-black">
        <Navbar cartCount={cart.length} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/menu" element={<Menu categories={categories} addToCart={(i) => setCart([...cart, i])} />} />
          <Route path="/about" element={<About />} />
          <Route path="/contact" element={<Contact />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/panier" element={<Panier cart={cart} />} />
        </Routes>
      </div>
    </Router>
  );
}
